shellCommands.command:
mkdir -p /tmp/theme-check && cat > /tmp/theme-check/check.mts <<'EOF'
import { loadStoredTheme, saveTheme, THEME_STORAGE_KEY } from '/home/sandbox/workspace/src/theme.ts';
import assert from 'node:assert/strict';

const store = new Map<string, string>();
(globalThis as any).window = {
  localStorage: {
    getItem: (k: string) => (store.has(k) ? store.get(k)! : null),
    setItem: (k: string, v: string) => void store.set(k, String(v)),
  },
};

assert.equal(loadStoredTheme(), 'light', 'empty storage -> default');
saveTheme('dark');
assert.equal(store.get(THEME_STORAGE_KEY), 'dark');
assert.equal(loadStoredTheme(), 'dark', 'after "reload" dark is restored');
saveTheme('light');
assert.equal(loadStoredTheme(), 'light');
store.set(THEME_STORAGE_KEY, 'purple');
assert.equal(loadStoredTheme(), 'light', 'invalid value -> default');

(globalThis as any).window = {
  localStorage: {
    getItem: () => { throw new Error('denied'); },
    setItem: () => { throw new Error('denied'); },
  },
};
assert.equal(loadStoredTheme(), 'light', 'storage throws on read -> default');
assert.doesNotThrow(() => saveTheme('dark'), 'storage throws on write -> no crash');
console.log('ALL OK');
EOF
cd /tmp/theme-check && node --experimental-strip-types check.mts 2>&1 | grep -v ExperimentalWarning
